"use client";

// Lets the dev voice page switch between hand-written fixtures and cases built from the real flood rasters.

import { useState } from "react";
import VoiceButton from "@/components/VoiceButton";

export type VoiceCase = { id: string; label: string; hazards: { address: string } };

export default function Picker({ cases }: { cases: VoiceCase[] }) {
  const [id, setId] = useState(cases[0].id);
  const current = cases.find((c) => c.id === id) ?? cases[0];
  return (
    <div className="flex flex-col gap-6">
      <label className="flex flex-col gap-1 text-sm text-zinc-600">
        Hazards data
        <select value={id} onChange={(e) => setId(e.target.value)} className="rounded border border-zinc-300 p-2 text-zinc-900">
          {cases.map((c) => (
            <option key={c.id} value={c.id}>
              {c.label}
            </option>
          ))}
        </select>
      </label>
      <p className="text-zinc-600">Address: {current.hazards.address}. Try “Did this place flood?”</p>
      {/* key: start a fresh voice session when the data changes */}
      <VoiceButton key={current.id} hazards={current.hazards} />
    </div>
  );
}
