"use client";

// Mic toggle for Grok Voice follow-up questions, with a live transcript.
// Pass the same hazards JSON the cards render; Grok reads it through the get_hazards tool.

import { useCallback } from "react";
import { useGrokVoice } from "@/lib/voice/useGrokVoice";

const LABEL = {
  idle: "Ask a question out loud",
  connecting: "Connecting…",
  listening: "Listening… ask away",
  thinking: "Thinking…",
  speaking: "Speaking…",
  error: "Try again",
} as const;

export default function VoiceButton({ hazards }: { hazards: unknown }) {
  const getHazards = useCallback(() => hazards, [hazards]);
  const { status, transcript, error, start, stop, active } = useGrokVoice(getHazards);

  return (
    <section className="flex flex-col gap-3">
      <button
        type="button"
        onClick={active ? stop : start}
        disabled={!hazards || status === "connecting"}
        aria-pressed={active}
        className={`rounded-full px-5 py-3 font-medium text-white transition disabled:opacity-50 ${
          active ? "bg-red-600 hover:bg-red-700" : "bg-blue-600 hover:bg-blue-700"
        }`}
      >
        {active ? `■ ${LABEL[status]}` : `🎙 ${LABEL[status]}`}
      </button>
      {error && <p className="text-sm text-red-600">{error}</p>}
      {transcript.length > 0 && (
        <ol className="flex flex-col gap-2 text-sm" aria-live="polite">
          {transcript.map((line, i) => (
            <li key={i} className={line.role === "user" ? "text-zinc-500" : "text-zinc-900 dark:text-zinc-100"}>
              <span className="font-semibold">{line.role === "user" ? "You: " : "Grok: "}</span>
              {line.text}
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}
